package org.dextur.reputation.storage;
import java.nio.file.*;
import java.util.*;
import org.dextur.reputation.api.*;
import org.dextur.reputation.application.*;
import org.dextur.reputation.domain.investigation.InvestigationData.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.params.*;
import org.junit.jupiter.params.provider.*;
import static org.junit.jupiter.api.Assertions.*;
class InvestigationSafetyTest {
    @org.junit.jupiter.api.io.TempDir Path directory;
    @ParameterizedTest @EnumSource(JsonStorage.Point.class)void crashPreservesWholeModerationGeneration(JsonStorage.Point point)throws Exception{var armed=new java.util.concurrent.atomic.AtomicBoolean();Path path=directory.resolve("json");StorageSnapshot before;try(var b=new JsonStorage(path,1048576,false,p->{if(armed.get()&&p==point)throw new java.io.IOException("simulated");})){InvestigationContract.configure(b,directory);var vote=InvestigationContract.cast(b,InvestigationContract.VOTER,VoteType.POSITIVE,InvestigationContract.NOW);before=b.snapshot();armed.set(true);assertThrows(Exception.class,()->b.moderate(InvestigationContract.request(Action.INVALIDATE,vote.operationId())));}try(var b=new JsonStorage(path,1048576,false)){var after=b.snapshot();if(point==JsonStorage.Point.AFTER_RENAME){assertEquals(0,after.protection().scores().getFirst().currentUnits());assertEquals(1,after.investigation().records().stream().filter(r->r.kind()==Kind.AUDIT).count());}else assertEquals(before,after);}}
    @Test void batchRollbackHasDurableCursorAndSafeResume()throws Exception{Files.writeString(directory.resolve("administration.yml"),new String(Objects.requireNonNull(getClass().getResourceAsStream("/administration.yml")).readAllBytes(),java.nio.charset.StandardCharsets.UTF_8).replace("batch-size: 10","batch-size: 1"));try(var b=SqlStorage.sqlite(directory.resolve("test.sqlite"),250,false)){InvestigationContract.configure(b,directory);InvestigationContract.cast(b,InvestigationContract.VOTER,VoteType.POSITIVE,InvestigationContract.NOW);InvestigationContract.cast(b,UUID.randomUUID(),VoteType.POSITIVE,InvestigationContract.NOW);var plan=b.plan(Action.INVALIDATE,"global",new Filter(null,InvestigationContract.TARGET,null,"",null,null,"","",null),"CONSOLE","batch",InvestigationContract.NOW);UUID id=UUID.randomUUID();b.begin(id,plan,InvestigationContract.NOW);assertEquals("1",b.advance(id,"CONSOLE",false,InvestigationContract.NOW).operation().values().get("cursor"));try(var c=b.connect();var s=c.createStatement()){s.execute("CREATE TRIGGER fail_batch BEFORE INSERT ON dr_investigation WHEN NEW.kind='AUDIT' BEGIN SELECT RAISE(FAIL,'simulated'); END");assertThrows(Exception.class,()->b.advance(id,"CONSOLE",false,InvestigationContract.NOW));var state=b.snapshot();var job=state.investigation().get(Kind.BULK,id);assertEquals("PAUSED",job.status());assertEquals("1",job.values().get("cursor"));assertEquals(350000,state.protection().scores().getFirst().currentUnits());assertEquals(1,state.investigation().records().stream().filter(r->r.kind()==Kind.DIAGNOSTIC).count());s.execute("DROP TRIGGER fail_batch");}assertEquals("COMPLETED",b.advance(id,"CONSOLE",false,InvestigationContract.NOW).operation().status());assertEquals(0,b.snapshot().protection().scores().getFirst().currentUnits());assertTrue(b.advance(id,"CONSOLE",false,InvestigationContract.NOW).mutations().isEmpty());}}
    @Test void sqliteSingleMutationRollsBackAndRepairsOnlyAuthoritativeProjection()throws Exception{try(var b=SqlStorage.sqlite(directory.resolve("test.sqlite"),250,false)){InvestigationContract.configure(b,directory);var vote=InvestigationContract.cast(b,InvestigationContract.VOTER,VoteType.POSITIVE,InvestigationContract.NOW);var before=b.snapshot();try(var c=b.connect();var s=c.createStatement()){s.execute("CREATE TRIGGER fail_audit BEFORE INSERT ON dr_investigation WHEN NEW.kind='AUDIT' BEGIN SELECT RAISE(FAIL,'simulated'); END");assertThrows(Exception.class,()->b.moderate(InvestigationContract.request(Action.INVALIDATE,vote.operationId())));assertEquals(before,b.snapshot());s.execute("DROP TRIGGER fail_audit");s.executeUpdate("UPDATE dr_profiles SET community_score=99,visible_score=99 WHERE player_uuid='"+InvestigationContract.TARGET+"'");b.moderate(InvestigationContract.request(Action.RECALCULATE_REPUTATION,InvestigationContract.TARGET));assertEquals(before.votes(),b.snapshot().votes());assertEquals(0,b.getOrCreate(InvestigationContract.TARGET,"global").visibleScore());}}}
    @Test void indexedCorruptionAndUnsupportedTrustModelBlockStartup()throws Exception{Path file=directory.resolve("test.sqlite");try(var b=SqlStorage.sqlite(file,250,false)){InvestigationContract.run(InvestigationContract.Scenario.ACTIVE,b,directory);try(var c=b.connect();var s=c.createStatement()){s.executeUpdate("UPDATE dr_investigation SET revision=revision+1");}}assertThrows(Exception.class,()->SqlStorage.sqlite(file,250,false));try(var c=java.sql.DriverManager.getConnection("jdbc:sqlite:"+file);var s=c.createStatement()){s.executeUpdate("UPDATE dr_investigation SET revision=revision-1");s.executeUpdate("UPDATE dr_trust SET payload=replace(payload,'\"modelVersion\":1','\"modelVersion\":2')");}assertThrows(Exception.class,()->SqlStorage.sqlite(file,250,false));}
    @ParameterizedTest @EnumSource(value=StorageType.class,names={"JSON","SQLITE"})void recoveryRewardAndFullRecalculationCannotLoseContribution(StorageType type)throws Exception{try(var b=StorageFixtures.local(directory,type,false)){RecoveryFixtures.seed(b,directory,RecoveryFixtures.rules(org.dextur.reputation.domain.recovery.RecoveryRules.Type.ACTIVE_PLAYTIME));b.features(PolicyConfiguration.load(directory));b.investigation(AdministrationConfiguration.load(directory));b.recover(RecoveryFixtures.request(org.dextur.reputation.domain.recovery.RecoveryData.Command.START,RecoveryFixtures.NOW));b.recover(RecoveryFixtures.sample(RecoveryFixtures.NOW,0,0));var request=new Request(UUID.randomUUID(),"global",Action.RECALCULATE_ALL,RecoveryFixtures.PLAYER,"CONSOLE","concurrent",-1,"",RecoveryFixtures.NOW.plusSeconds(10));InvestigationContract.race(()->b.moderate(request),()->b.recover(RecoveryFixtures.sample(RecoveryFixtures.NOW.plusSeconds(10),10,10)));assertEquals(-96,b.getOrCreate(RecoveryFixtures.PLAYER,"global").visibleScore());assertEquals(1,b.snapshot().recovery().get(RecoveryFixtures.PLAYER,"global").rewards().size());}}
    @ParameterizedTest @EnumSource(value=StorageType.class,names={"JSON","SQLITE"})void retentionDeletesOnlyExpiredLowRiskDiagnostics(StorageType type)throws Exception{try(var b=StorageFixtures.local(directory,type,false)){var time=java.time.Instant.now().minusSeconds(31L*86400).truncatedTo(java.time.temporal.ChronoUnit.MICROS);UUID important=UUID.randomUUID(),diagnostic=UUID.randomUUID(),none=new UUID(0,0);var records=List.of(new org.dextur.reputation.domain.investigation.InvestigationData.Record(important,Kind.AUDIT,"global","CONSOLE",none,none,"APPLIED",1,time,Map.of("action","PRESERVE","schema","1"),List.of()),new org.dextur.reputation.domain.investigation.InvestigationData.Record(diagnostic,Kind.DIAGNOSTIC,"global","CONSOLE",none,none,"FAILED",1,time,Map.of("action","DIAGNOSTIC","schema","1"),List.of()));b.prepareMigration();b.importEmpty(new StorageSnapshot(List.of(),List.of(),List.of(),ProtectionSnapshot.empty(),TierSnapshot.empty(),RecoverySnapshotData.empty(),AdministrationSnapshotData.empty(),new InvestigationSnapshotData(records)));b.finishMigration();b.investigation(AdministrationConfiguration.load(directory));assertNotNull(b.snapshot().investigation().get(Kind.AUDIT,important));assertNull(b.snapshot().investigation().get(Kind.DIAGNOSTIC,diagnostic));}}
    @Test void corruptedFormatSevenChecksumBlocksJsonStartup()throws Exception{Path directoryJson=directory.resolve("json");try(var b=new JsonStorage(directoryJson,1048576,false)){InvestigationContract.run(InvestigationContract.Scenario.RESTORE,b,directory);}Path file=directoryJson.resolve("state.json");Files.writeString(file,Files.readString(file).replace("Test moderation","Tampered moderation"));assertThrows(Exception.class,()->new JsonStorage(directoryJson,1048576,false));}
    @ParameterizedTest @EnumSource(value=StorageType.class,names={"JSON","SQLITE"})void relationshipBudgetsAreBoundedAndDeterministic(StorageType type)throws Exception{try(var b=StorageFixtures.local(directory,type,false)){InvestigationContract.configure(b,directory);var old=AdministrationConfiguration.load(directory);b.investigation(new Rules(old.pageSize(),old.maximumBulk(),old.batchSize(),old.confirmThreshold(),old.tokenSeconds(),old.maximumTokens(),1,1,1,old.recalculationEvents(),old.diagnosticRetentionDays(),old.maximumRecords(),old.jsonWarningPercent(),old.requireReason(),old.consoleAllowed()));for(int i=0;i<4;i++)InvestigationContract.cast(b,UUID.randomUUID(),VoteType.POSITIVE,InvestigationContract.NOW);var query=InvestigationContract.query(Section.RELATIONS,InvestigationContract.TARGET,null);var first=b.investigate(query);assertEquals("false",first.summary().get("complete"));assertTrue(first.rows().size()<=1);assertEquals(first,b.investigate(query));}}

}
